def by_category(category: str) -> list:
    return [p for p in PROMPTS if p["category"] == category]


def by_valence(valence: str) -> list:
    return [p for p in PROMPTS if p["valence"] == valence]


def summary() -> dict:
    from collections import Counter
    cats = Counter(p["category"] for p in PROMPTS)
    vals = Counter(p["valence"]  for p in PROMPTS)
    return {"total": len(PROMPTS), "by_category": dict(cats), "by_valence": dict(vals)}
